UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv4 Well-Known Multicast Addresses</div><p>IPv4 multicast uses 224.0.0.0/24 for link-local multicast. Each routing protocol listens on its own well-known address, so one packet reaches every router running the same protocol on the link.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>All routers</strong>: 224.0.0.2 is the well-known multicast address reserved for All routers.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>All OSPF routers</strong>: That is the multicast group for 224.0.0.5, not All routers.</li><li><span class="opt-tag wrong">Option C</span> <strong>All nodes</strong>: That is the multicast group for 224.0.0.1, not All routers.</li><li><span class="opt-tag wrong">Option D</span> <strong>All RIP routers</strong>: That is the multicast group for 224.0.0.9, not All routers.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Learn the 224.0.0.x set together: .1 all nodes, .2 all routers, .5 OSPF (Open Shortest Path First), .6 OSPF DR (Designated Router)/BDR (Backup Designated Router), .9 RIP (Routing Information Protocol), .10 EIGRP (Enhanced Interior Gateway Routing Protocol).</p></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1409';
